import{_ as a,o as r,c as e,aj as o}from"./chunks/framework.Cn87zHeG.js";const q=JSON.parse('{"title":"手柄遥操作","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"faq/controller.md","filePath":"faq/controller.md"}'),l={name:"faq/controller.md"};function n(s,t,i,h,d,c){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="手柄遥操作" tabindex="-1">手柄遥操作 <a class="header-anchor" href="#手柄遥操作" aria-label="Permalink to &quot;手柄遥操作&quot;">​</a></h1><p><a href="/onerobot-H1/downloads/faq/controller-guide.pdf">下载《手柄外观结构按键功能及使用说明》（PDF）</a></p><h2 id="q6" tabindex="-1">Q6. 手柄怎么开机？ <a class="header-anchor" href="#q6" aria-label="Permalink to &quot;Q6. 手柄怎么开机？ {#q6}&quot;">​</a></h2><p>按 <strong>Play（HOME）</strong> 键开机。首次连接和操作步骤见<a href="./../getting-started/first-use.html#controller">手柄遥操作</a>。</p><h2 id="q7" tabindex="-1">Q7. 手柄怎么和机器人重新配对？ <a class="header-anchor" href="#q7" aria-label="Permalink to &quot;Q7. 手柄怎么和机器人重新配对？ {#q7}&quot;">​</a></h2><ol><li>机器人<strong>开机</strong>并靠近机器人。</li><li>让手柄处于<strong>关机</strong>状态（若未关机，按 <strong>Back + B</strong> 直到灯灭）。</li><li>按住 <strong>Play + A</strong>（新手柄：长按 <strong>HOME</strong>）直到指示灯亮起，<strong>手柄震动即代表配对成功</strong>。</li></ol><p>新旧手柄的外观和操作说明见<a href="./../getting-started/first-use.html#controller">手柄遥操作</a>。</p><h2 id="q8" tabindex="-1">Q8. 手柄各按键都是什么功能？ <a class="header-anchor" href="#q8" aria-label="Permalink to &quot;Q8. 手柄各按键都是什么功能？ {#q8}&quot;">​</a></h2><p>完整按键表见<a href="./../getting-started/first-use.html#controller-buttons">手柄按键功能</a>，布局图见<a href="./../getting-started/first-use.html#controller">手柄准备</a>。Start 用于进入主臂控制从臂模式或重置姿态；Back 用于退出当前模式、进入待机状态，配套固件会执行归位、升降及头部校准。<strong>操作这两个按键前，应清空机器人运动范围。</strong></p><h2 id="q9" tabindex="-1">Q9. LT / RT 加减速控制的是升降还是底盘？ <a class="header-anchor" href="#q9" aria-label="Permalink to &quot;Q9. LT / RT 加减速控制的是升降还是底盘？ {#q9}&quot;">​</a></h2><p>取决于当前控制对象：控制升降时调节升降速度，控制底盘时调节底盘速度，<strong>两者独立调节</strong>。</p><h2 id="q10" tabindex="-1">Q10. 手柄使用有哪些注意事项？ <a class="header-anchor" href="#q10" aria-label="Permalink to &quot;Q10. 手柄使用有哪些注意事项？ {#q10}&quot;">​</a></h2><ul><li>使用主从遥操作系统时，<strong>主臂、从臂、手柄、笔记本按交付配套使用</strong>，避免混用其它测试设备。</li><li>操作时<strong>禁止重复按同一个按键</strong>——会造成指令重复下发，导致机器人大幅度抖动。</li><li><strong>禁止按未知功能的按键。</strong></li></ul><p>操作前请阅读<a href="./../getting-started/first-use.html#controller-safety">手柄操作注意事项</a>。</p><h2 id="q11" tabindex="-1">Q11. 手柄没反应 / 配不上怎么办？ <a class="header-anchor" href="#q11" aria-label="Permalink to &quot;Q11. 手柄没反应 / 配不上怎么办？ {#q11}&quot;">​</a></h2><p>先按 <strong>Back + B</strong> 让手柄关机（灯灭），确认机器人已开机且手柄靠近机器人，再按 <a href="#q7">Q7 的步骤</a>重新配对。新旧手柄的配对按键不同，请按对应说明操作。</p>',16)])])}const f=a(l,[["render",n]]);export{q as __pageData,f as default};
